/** Generated files: systemd units, env files and the optional PostgreSQL/Redis compose file. */
import { generateSecret, renderEnv, type EnvEntry } from './env-file.js';
import type { Project } from './project.js';

/** npm install scripts the project's dependency tree needs (npm 12 blocks all others). */
export const ALLOW_SCRIPTS: Readonly<Record<string, true>> = Object.freeze({
  '@prisma/engines': true,
  argon2: true,
  'better-sqlite3': true,
  'cpu-features': true,
  'msgpackr-extract': true,
  prisma: true,
  sharp: true,
  ssh2: true,
});

export const SERVER_SECRET_NAMES = [
  'API_SECRET',
  'JWT_SECRET',
  'NODE_MANAGER_SECRET',
  'AUDIT_HMAC_SECRET',
  'RESULT_SIGNING_SECRET',
  'LOG_INGEST_SIGNING_SECRET',
  'CREDENTIAL_ROTATION_KEY',
  'METRICS_TOKEN',
  'WEBHOOK_ENCRYPTION_KEY',
] as const;

export interface ServiceUnitOptions {
  project: Project;
  nodePath: string;
  /** systemd system scope only: the account the services run as. */
  serviceUser?: string;
  afterUnits: string[];
  /** Extra CA trusted by the server when it calls agents (the self-signed certificate on one host). */
  extraCaFile?: string;
}

function unitHeader(description: string, afterUnits: string[]): string[] {
  return [
    '# Generated by `magnus init`; `magnus upgrade` keeps it pointing at ./current.',
    '[Unit]',
    `Description=${description}`,
    `After=network-online.target${afterUnits.length ? ` ${afterUnits.join(' ')}` : ''}`,
    'Wants=network-online.target',
    '',
    '[Service]',
    'Type=simple',
  ];
}

function hardening(options: ServiceUnitOptions, writable: string[]): string[] {
  const system = options.project.state.scope === 'system';
  return [
    'Restart=on-failure',
    'RestartSec=5',
    'UMask=0077',
    'NoNewPrivileges=true',
    'PrivateTmp=true',
    ...(system ? ['ProtectSystem=strict', ...writable.map((path) => `ReadWritePaths=${path}`)] : []),
    '',
    '[Install]',
    `WantedBy=${system ? 'multi-user.target' : 'default.target'}`,
    '',
  ];
}

export function serverUnit(options: ServiceUnitOptions): string {
  const { project } = options;
  return [
    ...unitHeader('Magnus server', options.afterUnits),
    ...(options.serviceUser ? [`User=${options.serviceUser}`] : []),
    `WorkingDirectory=${project.dir}`,
    `Environment=MAGNUS_PROJECT_DIR=${project.dir}`,
    `Environment=MAGNUS_RUNTIME_FILE=${project.path('run', 'server-runtime.json')}`,
    ...(options.extraCaFile ? [`Environment=NODE_EXTRA_CA_CERTS=${options.extraCaFile}`] : []),
    `ExecStart=${options.nodePath} ${project.bin('current', 'magnus-server')} start --env-file ${project.envFile('server')}`,
    ...hardening(options, [project.dir]),
  ].join('\n');
}

export function uiUnit(options: ServiceUnitOptions): string {
  const { project } = options;
  const dataDir = project.path('ui-data');
  return [
    ...unitHeader('Magnus console', [...options.afterUnits, `${project.state.units.server}.service`]),
    ...(options.serviceUser ? [`User=${options.serviceUser}`] : []),
    `WorkingDirectory=${dataDir}`,
    `ExecStart=${options.nodePath} ${project.bin('current', 'magnus-ui')} start --env-file ${project.envFile('ui')} --data-dir ${dataDir}`,
    ...hardening(options, [dataDir, project.path('run')]),
  ].join('\n');
}

export interface DepsSettings {
  postgresPort: number;
  redisPort: number;
  postgresPassword: string;
  redisPassword: string;
}

/** PostgreSQL 17 and Redis 7 on loopback, for hosts without their own. */
export function depsCompose(): string {
  return `# Generated by \`magnus init\`: PostgreSQL and Redis for Magnus, bound to loopback.
name: magnus-deps
services:
  postgres:
    image: postgres:17-alpine
    restart: unless-stopped
    environment:
      POSTGRES_USER: magnus
      POSTGRES_DB: magnus
      POSTGRES_PASSWORD: \${POSTGRES_PASSWORD:?}
    ports:
      - "127.0.0.1:\${POSTGRES_PORT:-5432}:5432"
    volumes:
      - postgres:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U magnus -d magnus"]
      interval: 5s
      timeout: 5s
      retries: 20
  redis:
    image: redis:7-alpine
    restart: unless-stopped
    command: ["redis-server", "--requirepass", "\${REDIS_PASSWORD:?}", "--appendonly", "yes"]
    ports:
      - "127.0.0.1:\${REDIS_PORT:-6379}:6379"
    volumes:
      - redis:/data
    healthcheck:
      test: ["CMD-SHELL", "redis-cli ping | grep -qE 'PONG|NOAUTH'"]
      interval: 5s
      retries: 20
volumes:
  postgres:
  redis:
`;
}

export function depsEnv(settings: DepsSettings): string {
  return renderEnv('PostgreSQL and Redis for Magnus (docker compose --env-file). Keep this file private.', [{
    title: 'Dependencies',
    entries: [
      { name: 'POSTGRES_PASSWORD', value: settings.postgresPassword },
      { name: 'POSTGRES_PORT', value: String(settings.postgresPort) },
      { name: 'REDIS_PASSWORD', value: settings.redisPassword },
      { name: 'REDIS_PORT', value: String(settings.redisPort) },
    ],
  }]);
}

export interface ServerEnvSettings {
  databaseUrl: string;
  redisUrl: string;
  port: number;
  publicUrl: string;
  uiOrigin: string;
  tlsCert: string;
  tlsKey: string;
  home: string;
  backupDir: string;
  autoMigrate: boolean;
}

export function serverEnv(settings: ServerEnvSettings, secrets: Record<string, string>): string {
  const entries = (names: readonly string[]): EnvEntry[] => names.map((name) => ({ name, value: secrets[name] ?? generateSecret() }));
  return renderEnv('magnus-server configuration, generated by `magnus init`. Keep this file private (0600).\n'
    + 'Every variable: `magnus-server env-schema --format table`.', [
    { title: 'Core', entries: [
      { name: 'NODE_ENV', value: 'production' },
      { name: 'MAGNUS_HOME', value: settings.home, comment: 'Server data: audit logs, credential rotation state.' },
      { name: 'MAGNUS_BACKUP_DIR', value: settings.backupDir, comment: 'Pre-migration database dumps.' },
      { name: 'DATABASE_URL', value: settings.databaseUrl },
      { name: 'REDIS_URL', value: settings.redisUrl },
    ] },
    { title: 'Listener', entries: [
      { name: 'CONTROL_API_PORT', value: String(settings.port) },
      { name: 'CONTROL_API_URL', value: settings.publicUrl, comment: 'URL agents use to reach this server.' },
      { name: 'CORS_ORIGIN', value: settings.uiOrigin },
      { name: 'DASHBOARD_PUBLIC_ORIGIN', value: settings.uiOrigin },
      { name: 'TLS_CERT_PATH', value: settings.tlsCert },
      { name: 'TLS_KEY_PATH', value: settings.tlsKey },
    ] },
    { title: 'Secrets (generated; each one distinct)', entries: entries(SERVER_SECRET_NAMES) },
    { title: 'Upgrades (set any of these to false to run your own release process)', entries: [
      { name: 'MAGNUS_AUTO_MIGRATE', value: String(settings.autoMigrate), comment: 'Back up and apply pending migrations at startup.' },
      { name: 'MAGNUS_AUTO_MIGRATE_BACKUP', value: 'true' },
      { name: 'MAGNUS_UPDATE_CHECK', value: 'true', comment: 'Daily npm registry check; shows new releases in the console.' },
      { name: 'MAGNUS_AGENT_UPGRADES', value: 'true' },
    ] },
  ]);
}

export interface UiEnvSettings {
  serverUrl: string;
  serverCa?: string;
  redisUrl: string;
  publicOrigin: string;
  port: number;
  tlsCert: string;
  tlsKey: string;
  adminUser: string;
  adminPasswordHash: string;
}

export function uiEnv(settings: UiEnvSettings, apiSecret: string): string {
  return renderEnv('magnus-ui configuration, generated by `magnus init`. Keep this file private (0600).\n'
    + 'Every variable: `magnus-ui env-schema`.', [
    { title: 'Server', entries: [
      { name: 'CONTROL_API_URL', value: settings.serverUrl },
      ...(settings.serverCa ? [{ name: 'CONTROL_API_CA_PATH', value: settings.serverCa }] : []),
      { name: 'API_SECRET', value: apiSecret, comment: 'Same value as the server\'s API_SECRET.' },
      { name: 'REDIS_URL', value: settings.redisUrl },
    ] },
    { title: 'Console', entries: [
      { name: 'DASHBOARD_PUBLIC_ORIGIN', value: settings.publicOrigin },
      { name: 'PORT', value: String(settings.port) },
      { name: 'TLS_CERT_PATH', value: settings.tlsCert },
      { name: 'TLS_KEY_PATH', value: settings.tlsKey },
      { name: 'SESSION_SECRET', value: generateSecret() },
      { name: 'CONTROL_NODE_CREDENTIAL_KEY', value: generateSecret() },
      { name: 'DASHBOARD_ADMIN_USERNAME', value: settings.adminUser },
      { name: 'DASHBOARD_ADMIN_PASSWORD_HASH', value: settings.adminPasswordHash },
    ] },
  ]);
}

/** package.json of one installed version. */
export function versionPackageJson(version: string, dependencies: Record<string, string>,
  overrides: Record<string, string | Record<string, string>> = {}): string {
  return `${JSON.stringify({
    name: `magnus-project-${version}`,
    version,
    private: true,
    description: 'Magnus server and console, installed and upgraded by @hivemagnus/magnus. Do not edit; run `magnus upgrade`.',
    type: 'module',
    dependencies,
    ...(Object.keys(overrides).length ? { overrides } : {}),
    allowScripts: ALLOW_SCRIPTS,
  }, null, 2)}\n`;
}
